)
)
select e.mig as "الترقية", e.kind as "النوع", e.name as "الكيان الناقص"
from expected e
where (e.kind in ('table','view') and to_regclass('public.' || e.name) is null)
   or (e.kind = 'function' and not exists (
         select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
          where n.nspname = 'public' and p.proname = e.name))
order by e.mig;
